if GetLocale() ~= "koKR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "근접 공격 전담"
L["rm.era.rogue.dps.Description"] = "1–60레벨, 모든 전문 분야용이며 하드코어와 자수성가 서버에서도 쓰입니다. 시뮬레이터, Icy Veins, Wowhead를 바탕으로 만들었습니다. 은신 상태에서: 사전계획, 대상이 나를 바라보지 않으면 단검으로 매복, 혼자일 때 비열한 습격, 공격대 밖에서 목조르기. 전투 중: 반격, 정예나 생명력이 많은 대상에게 난도질이 없으면 연계 점수 1점부터 난도질(마지막 3초에 5점으로 갱신), 그룹에서 약점 노출 연마 2/2가 있고 아무도 방어구 가르기를 하지 않으면 5점에서 약점 노출, 곧 죽을 대상에게 2점 절개, 그 외에는 5점에서 절개, 5점을 넘으면 연계 점수 생성 기술 없음. 연계 점수 생성 기술은 배운 것을 따릅니다: 공격대 밖에서 그림자 일격과 과다출혈, 대상이 나를 바라보지 않으면 단검으로 기습, 그 외에는 사악한 일격. 알림: 무기마다 독(보조 무기가 있으면 보조 무기에 맹독), 발차기, 엉겅퀴 차, 난도질이 걸려 있을 때 정예나 적 둘에게 폭풍의 칼날과 아드레날린 촉진, 5점에서 냉혈, 혼자일 때 다치면 회피. 소멸, 후려치기, 마음가짐, 급소 가격, 종족 특성은 꺼진 상태로 나열되며, 교란, 전력 질주, 실명, 기절시키기, 위치 선정은 직접 판단합니다."
L["rm.era.rogue.dps.simulator.Name"] = "도검, 자동 공격에 맞춘 사악한 일격 (시뮬레이터)"
L["rm.era.rogue.dps.simulator.Description"] = "도검류 전문화를 위한 시뮬레이터의 \"빡빡한\" 전투 순서로, 추천 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 추가 도검 공격이 자동 공격을 늦추지 않도록, 기력이 거의 가득 찼거나 대상이 곧 죽는 경우가 아니면 사악한 일격은 주 무기 자동 공격 직후에만 사용합니다(다음 공격까지 2.0초 이상, 공격 속도 2.6–2.8 도검 기준이며 복제본에서 바꾸세요). 5점 절개도 난도질, 가득 찬 기력 또는 죽어 가는 대상을 기다립니다. 그 외에는 추천 기본 제공 로테이션과 같습니다."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "근접 공격 전담, 5점 마무리 (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Warcraft Tavern 방식으로, 추천 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 가혹한 일격이 되돌려 주도록 모든 마무리 기술은 연계 점수 5점을 기다립니다. 난도질은 2등급(42레벨)부터 없거나 끝나 갈 때 사용하고, 그 외에는 절개를 사용합니다. 낮은 점수의 난도질, 죽기 직전 대상의 절개, 약점 노출(전사의 방어구 가르기가 대신함)은 없습니다. 시작 기술, 연계 점수 생성 기술, 알림은 추천 기본 제공 로테이션과 같습니다."
L["rm.forever.rogue.dps.Name"] = "근접 공격 전담"
L["rm.forever.rogue.dps.Description"] = "1레벨부터 60레벨까지 모든 도적 전문화를 위한 근접 공격 로테이션으로, Icy Veins, Wowhead, Warcraft Tavern을 바탕으로 만들었습니다. 연계 점수 생성 기술은 배운 기술을 따릅니다: 절단(다섯 번째 점수는 사악한 일격), 과다출혈, 대상이 나를 바라보지 않으면 기습, 그 외에는 사악한 일격. 은신 상태에서는 사전계획으로 시작하고, 혼자일 때 비열한 습격, 그룹 정예 상대 잠행이면 목조르기, 그 외에는 매복 또는 목조르기를 사용합니다. 난도질과 맹독을 유지하고, 그룹에서 정예 상대로 방어구 가르기 5중첩을 건 전사가 없으면 약점 노출을 사용하며, 이후 연계 점수 5점을 파열(잠행, 긴 전투) 또는 절개에 쓰고, 5점을 넘겨 쌓지 않습니다. 알림: 각 무기의 독, 발차기, 다수의 적과 정예 상대 폭풍의 칼날과 아드레날린 촉진, 냉혈, 회피, 교란, 엉겅퀴 차, 마음가짐. 직접 판단할 것: 소멸, 전력 질주, 급소 가격, 실명, 기절시키기, 위치 선정. Forever는 전투 데이터를 제한하므로 Rotation Master는 이 기본 제공 로테이션을 참고용으로만 표시하며 아직 자동으로 선택하지 않습니다."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "잠행, 매복 빌드 (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Warcraft Tavern의 매복/극악무도 잠행 빌드입니다: 모든 시작 기술에 사전계획과 매복, 극악무도가 허용할 때마다 다시 매복, 연계 점수 생성은 뒤에서 기습(대상이 나를 바라보면 과다출혈), 재사용 대기시간마다 그림자 일격, 5점에서는 난도질 후 절개를 사용하며 파열은 쓰지 않습니다. 방어 전담이 붙잡은 우두머리에게 다시 매복하도록 소멸을 알려 줍니다. 극악무도 특성을 찍었다면 추천 도적 기본 제공 로테이션 대신 이것을 선택하세요. 잠행이 주 특성 트리이고 극악무도를 찍은 경우에 적용됩니다. 독과 재사용 대기시간 알림은 추천 기본 제공 로테이션과 같습니다. 추천 도적 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "잠행, 목조르기 빌드 (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "Wowhead의 잠행 로테이션입니다: 모든 시작 기술에 사전계획과 목조르기를 사용하고, 마지막 목조르기가 끝나면 다시 목조르기로 시작하기 위해 로테이션 안에서 소멸(그다음 마음가짐)을 사용합니다. 난도질 유지, 그룹에서 약점 노출, 5점 마무리 기술로 파열, 연계 점수 생성 기술은 과다출혈만 사용합니다. 탈출 수단인 소멸을 공격에 쓰므로 신중하게 선택하세요. 잠행이 주 특성 트리이고 Dirty Deeds 특성을 찍었으며 사전계획을 배운 경우에 적용됩니다. 독과 재사용 대기시간 알림은 추천 기본 제공 로테이션과 같습니다. 추천 도적 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
L["rm.mop.rogue.assassination.Name"] = "추천"
L["rm.mop.rogue.assassination.Description"] = "10레벨부터 90레벨까지 암살에게 권장합니다(5단계용 시뮬레이터와 Wowhead, Icy Veins의 레벨업 단계). 은신 상태에서 혼자일 때는 비열한 습격, 그 외에는 절단(사각 지대 시 속결, 단검 필요)으로 시작합니다. 난도질을 유지하고(60레벨부터 독살로 갱신) 대상에 파열을 유지하며, 파열이 지속되는 동안 5점을 독살에 쓰고, 선견지명이 없으면 독살 강화 효과를 계속 유지하기 위해 4점을 쓴 뒤, 죽음의 표적, 35% 미만이거나 사각 지대 시 속결(주무기가 단검이어야 함), 절단을 사용합니다. 적이 넷 이상 나와 싸우면: 난도질, 적이 일곱이면 혈폭풍, 파열, 독살, 칼날 부채; 다른 대상에 파열을 거는 것은 직접 판단합니다. 혼자일 때는 생명력이 낮으면 만회와 급소 가격을 추가합니다. 알림: 독, 발차기, 긴 전투에서 원한, 원한과 함께 어둠의 칼날, 원한 중 소멸과 마음가짐, 원거리에서 그림자 밟기, 혼자일 때 회피. 직접 판단할 것: 속임수 거래와 약점 노출(나열되지만 꺼짐), 교란, 전력 질주, 위치 선정."
L["rm.mop.rogue.assassination.icyveins.Name"] = "5점 독살 (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "기본적으로 꺼져 있습니다. Icy Veins와 Method의 순서입니다: 은신 상태 절단을 위해 재사용 대기시간마다 소멸, 전투가 충분히 길면 재사용 대기시간마다 원한, 독살은 5점에서만, 파열 유지, 35% 미만이거나 사각 지대 시 속결, 절단. 적이 넷에서 여덟이면: 3점 이상으로 파열과 함께 칼날 부채; 아홉 이상이면 칼날 부채와 독살만. 권장 암살 기본 제공 로테이션은 대신 더 새로운 5단계 조언을 따릅니다. 이것을 사용하려면 이것을 켜고 권장 로테이션을 끄세요."
L["rm.mop.rogue.combat.Name"] = "추천"
L["rm.mop.rogue.combat.Description"] = "10레벨부터 90레벨까지 전투에게 권장합니다(5단계용 Wowhead와 시뮬레이터). 오그리마 공성전 패치 이후 사악한 일격의 기력 소모가 50이므로, 약점 공격이 연계 점수 생성 기술이며 사악한 일격은 아드레날린 촉진과 함께 피의 욕망이나 영웅심 중일 때만(그리고 20레벨 전에) 사용합니다. 혼자일 때 비열한 습격, 그 외에는 매복으로 시작합니다. 2점부터 난도질과 대상의 약점 공격을 유지하고, 약점 공격이 걸려 있는 동안에만 5점을 쓰며(난도질, 폭풍의 칼날 없이 긴 단일 대상 전투에서 파열, 절개), 5점에서는 기력을 기다립니다. 적이 여덟 이상이면: 난도질, 혈폭풍, 칼날 부채. 혼자일 때는 만회와 급소 가격을 추가합니다. 알림: 독, 발차기, 적이 둘 이상이면 폭풍의 칼날 켜기와 다시 끄기, 기력이 낮을 때 어둠의 칼날과 함께 아드레날린 촉진, 광기의 학살자, 깊은 통찰 중 매복을 위한 소멸과 마음가짐, 그림자 밟기, 혼자일 때 회피. 직접 판단할 것: 속임수 거래와 약점 노출(나열되지만 꺼짐), 교란, 매복을 위해 대상 뒤에 서기."
L["rm.mop.rogue.combat.hekili.Name"] = "선견지명 (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "기본적으로 꺼져 있습니다. 선견지명을 쓰는 전투를 위한 Hekili MoP 순서입니다: 피의 욕망 중에도 약점 공격만 연계 점수 생성 기술로 사용합니다. 마무리 기술은 깊은 통찰, 선견지명 충전 4회, 또는 어둠의 칼날이 돌아올 때를 기다린 뒤 난도질, 오래 사는 대상 하나나 둘에게 파열, 적 일곱에게 혈폭풍, 절개를 사용합니다. 난도질은 도적의 간계 11중첩에서 일찍 갱신하며, 적이 넷부터 칼날 부채. 선견지명을 찍었을 때만 적용됩니다. 사용하려면 이것을 켜고 권장 전투 기본 제공 로테이션을 끄세요."
L["rm.mop.rogue.combat.icyveins.Name"] = "사악한 일격 생성 (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "기본적으로 꺼져 있으며, 5단계에서는 대체되었습니다. 오그리마 공성전 패치 이전의 Icy Veins, Warcraft Tavern, Method, wowtbc.gg 순서입니다: 난도질, 약점 공격 유지, 긴 단일 대상 전투에서 5점 파열과 절개, 연계 점수 생성 기술은 사악한 일격. 알림과 무리 대응은 권장 전투 기본 제공 로테이션과 같습니다. 이 공략을 따를 때만 선택하세요. 이것을 켜고 권장 로테이션을 끄세요."
L["rm.mop.rogue.subtlety.Name"] = "추천"
L["rm.mop.rogue.subtlety.Description"] = "10레벨부터 90레벨까지 어둠의 집중을 쓰는 잠행에게 권장합니다(5단계용 시뮬레이터와 Wowhead). 은신이나 어둠의 춤 중에는: 사전계획, 전투 전 난도질, 5점에서 마무리 기술, 매복, 목조르기. 그 밖에서는: 난도질; 5점에서 난도질과 파열이 곧 끝나면 갱신하고, 둘 다 지속되는 동안 절개; 죽음의 표적; 출혈을 유지하기 위한 과다출혈; 대상이 나를 공격하지 않으면 기습(단검을 든 경우), 그 외에는 과다출혈. 적이 셋 이상이면: 난도질, 혈폭풍, 절개, 칼날 부채. 혼자일 때는 만회와 급소 가격을 추가합니다. 알림: 독, 발차기, 난도질과 파열이 걸려 있을 때 기력 75에서 어둠의 춤, 약점 포착이 끝나 갈 때 소멸, 마음가짐, 어둠의 춤과 은신 밖에서 어둠의 칼날, 그림자 밟기, 혼자일 때 회피. 직접 판단할 것: 대상 뒤에 서기(RM은 방향을 볼 수 없음), 속임수 거래와 약점 노출(나열되지만 꺼짐)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "기만 (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "1단계 특성이 기만일 때(Warcraft Tavern의 빌드) 어둠의 집중 기본 제공 로테이션 대신 자동으로 선택됩니다. 전투 전 사전계획과 난도질; 은신, 어둠의 춤 또는 기만 지속 중에는 5점에서 마무리 기술, 그다음 가능한 한 자주 매복. 적이 둘이나 셋이면: 파열을 유지하고 5점을 절개 대신 혈폭풍에 사용하며, 넷 이상이면 칼날 부채를 추가합니다. 단일 대상: 난도질, 파열, 절개, 출혈을 위한 과다출혈, 뒤에서 단검으로 기습, 그 외에는 과다출혈. 어둠의 춤과 소멸은 난도질이 걸려 있을 때 기력 60에서 알림으로 표시되며, Tavern이 권하는 대로 장신구 발동에 맞추는 것은 직접 판단합니다."
L["rm.mop.rogue.unspecialized.Name"] = "전문화 없음"
L["rm.mop.rogue.unspecialized.Description"] = "1–9레벨이나 아직 전문화를 고르지 않은 도적용이며, 전문화를 고르면 각 전문화의 기본 제공 로테이션이 넘겨받습니다. 은신 상태에서 혼자일 때 비열한 습격, 매복 또는 사악한 일격으로 시작하고, 전투 밖에서는 은신을 제안합니다. 2점부터 난도질, 혼자이고 다쳤으면 만회와 급소 가격, 4점(대상이 곧 죽으면 2점)에서 절개, 사악한 일격. 알림: 배운 뒤에는 독, 발차기, 혼자일 때 회피."
L["rm.retail.rogue.assassination.Name"] = "Blizzard 전투 보조"
L["rm.retail.rogue.assassination.Description"] = "한밤에서 암살 전문화에 권장됩니다. 이제 게임이 전투 중 출혈, 강화 효과, 기력, 재사용 대기시간, 생명력을 애드온에 숨기므로, 이 로테이션은 Blizzard의 자체 전투 보조 제안(은신 시작 기술, 목조르기, 파열, 독살, 죽음표식, 왕의 파멸을 처리하는 원버튼 로테이션)을 보여 주며, 시전 중이거나 적을 대상으로 지정하지 않았을 때는 멈춥니다. 제안에서 빠진 것에 대한 알림: 전투 사이에 치명적인 독과 비치명적인 독 하나씩, 그리고 은신, 전투 중 은신 상태가 아닐 때 소멸, 차단 가능한 시전에 발차기(게임이 시전을 읽도록 허용하는 곳에서만 강조됩니다). Retail에서는 생명력이 숨겨지므로 진홍색 약병은 직접 판단합니다."
L["rm.retail.rogue.assassination.icyveins.Name"] = "참고용 (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins와 SimulationCraft의 순서는 타이머에 따라 출혈을 유지하는데, 한밤은 이를 전투 중 숨기며, Retail에서는 기력이 숨겨지므로 기력 모으기는 빠져 있습니다. 은신 상태에서는 목조르기, 그다음 매복. 연계 점수가 가득 차지 않았을 때 남은 시간이 30% 이하이면 목조르기, 5점 이상이고 남은 시간이 30% 이하이면 파열; 연계 점수 5점 이상에서는 최후의 일격 또는 독살; 그 미만에서는 적이 셋 이상이면 혈폭풍, 가까이에 둘 이상이면 칼날 부채, 매복, 절단. 알림: 두 출혈이 모두 걸려 있을 때 죽음표식, 그와 함께 왕의 파멸, 죽음표식이 준비되었을 때 소멸, 죽음추적자의 징표가 있는 대상에게 독칼, 전투 중 준비될 때마다 엉겅퀴 차, 그리고 공용 독, 은신, 발차기 알림."
L["rm.retail.rogue.initial.Name"] = "Blizzard 전투 보조"
L["rm.retail.rogue.initial.Description"] = "전문화를 선택하기 전(게임이 도적의 초기 전문화를 보고하는 동안)에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 모든 도적 기본 제공 로테이션이 공유하는 알림을, 해당 주문을 배운 뒤에 각각 제공합니다. 10레벨에 전문화를 선택하면 해당 전문화의 기본 제공 로테이션이 대신합니다."
L["rm.retail.rogue.outlaw.Name"] = "Blizzard 전투 보조"
L["rm.retail.rogue.outlaw.Description"] = "한밤에서 무법 전문화에 권장됩니다. Blizzard의 전투 보조 제안을 보여 주며(은신 시작 기술, 뼈주사위, 폭풍의 칼날, 아드레날린 촉진, 미간 적중, 마무리 기술을 처리합니다), 시전 중이거나 적을 대상으로 지정하지 않았을 때는 멈춥니다. 제안에서 빠진 것에 대한 알림: 전투 사이에 독과 은신, 전투 중 은신 상태가 아닐 때 소멸, 발차기. Retail에서는 생명력이 숨겨지므로 진홍색 약병은 직접 판단합니다. 도박의 연속은 직접 판단합니다: 게임이 뼈주사위 강화 효과의 개수를 숨기기 때문입니다."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "참고용 (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins, SimulationCraft와 Wowhead의 순서는 뼈주사위 강화 효과, 기회 중첩, 기력을 읽는데, 한밤은 이를 전투 중 숨깁니다. 은신 상태에서는 매복. 연계 점수가 최대치보다 1 적거나 그 이상이면: 미간 적중, 광기의 학살자, 최후의 일격, 속결. 그 외에는 배포가 있을 때 매복, 기회 6중첩에서 권총 사격(연계 점수가 적으면 3중첩), 매복, 사악한 일격. 알림: 뼈주사위 효과가 하나도 없으면 뼈주사위, 연계 점수 2점 이하에서 아드레날린 촉진, 적이 둘 이상이면 폭풍의 칼날 유지, 질풍 칼날, 아드레날린 촉진, 미간 적중, 질풍 칼날이 모두 재사용 대기 중이면 마음가짐. 도박의 연속은 수동으로 사용합니다."
L["rm.retail.rogue.subtlety.Name"] = "Blizzard 전투 보조"
L["rm.retail.rogue.subtlety.Description"] = "한밤에서 잠행 전문화에 권장됩니다. Blizzard의 전투 보조 제안을 보여 주며(은신 시작 기술, 어둠의 칼날, 피아귀의 이빨, 어둠의 춤, 은밀한 기술, 마무리 기술을 처리합니다), 시전 중이거나 적을 대상으로 지정하지 않았을 때는 멈춥니다. 제안에서 빠진 것에 대한 알림: 전투 사이에 독과 은신, 차단 가능한 시전에 발차기. Retail에서는 생명력이 숨겨지므로 진홍색 약병은 직접 판단합니다."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "참고용 (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins와 SimulationCraft의 순서는 은밀한 기술을 위해 어둠의 춤을 아껴 두고 어둠의 춤, 어둡고 어두운 밤, 기력을 읽는데, 한밤은 이를 전투 중 숨깁니다. 전투 전 은신 상태: 그림자 일격. 연계 점수가 최대치보다 1 적거나 그 이상이면: 어둡고 어두운 밤이 있을 때 절개, 어둠의 춤 중 은밀한 기술, 최후의 일격, 적이 셋 이상이면 검은 화약, 절개. 그 외에는 그림자 일격, 둘 이상이면 표창 폭풍, 어둠칼날 또는 기습. 알림: 어둠의 춤 중 피아귀의 이빨, 어둠의 춤이 준비되었을 때 어둠의 칼날, 은밀한 기술이 준비되었거나 어둠의 칼날이 활성화되어 있을 때 연계 점수 2점 이하(또는 6점 이상)에서 어둠의 춤, 은신 상태가 아닐 때 연계 점수 2점 이하에서 소멸."
L["rm.sod.rogue.dps.Name"] = "근접 공격 전담 (SoD)"
L["rm.sod.rogue.dps.Description"] = "디스커버리 시즌 1–60레벨용이며 룬은 새긴 대로 사용합니다. 시뮬레이터 6단계, Icy Veins, Zockify 8단계를 바탕으로 만들었습니다. 은신 상태에서: 그림자 일격, 그룹에서 목조르기, 단검을 든 기습 빌드라면 매복, 혼자일 때 비열한 습격. 적이 셋 이상 나와 싸우면: 나팔총, 혈폭풍, 칼날 부채를 먼저. 그다음 극악무도 발동 시 매복(단검을 든 경우), 사브르 베기 3중첩 유지, 독 4중첩에서 독 칼, 2점부터 난도질(단도직입을 새기지 않았다면 4점부터 갱신), 아무도 방어구 가르기를 하지 않거나 피부 독을 유지하지 않으면 약점 노출 담당, 살육자를 새겼다면 출혈(혈폭풍, 없으면 파열; 사브르 베기가 있으면 없음), 5점에서 독살(새기기 전에는 절개), 그리고 장갑 룬에 따른 연계 점수 생성 기술: 절단, 사브르 베기, 기습(단검을 든 경우), 그 외에는 사악한 일격. 알림: 무기마다 임시 마법부여, 발차기, 엉겅퀴 차, 폭풍의 칼날, 아드레날린 촉진, 냉혈, 회피, 그리고 잠행의 대가를 새겼다면 갱신용 소멸과 마음가짐."
L["rm.sod.rogue.dps.icyveins.Name"] = "근접 공격 전담, 살육자용 파열 (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "Icy Veins의 디스커버리 시즌 순서로, 추천 디스커버리 시즌 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 모든 마무리 기술은 연계 점수 5점에서, 먼저 없거나 끝나 갈 때 난도질, 그다음 살육자를 새겼다면 파열 유지, 그다음 독살; 독 칼은 독 5중첩에서만; 적이 셋이면 나팔총 또는 칼날 부채. 시작 기술, 연계 점수 생성 기술, 알림은 추천 기본 제공 로테이션과 같으며, 피부 독 담당은 직접 판단합니다."
L["rm.sod.rogue.dps.zockify.Name"] = "근접 공격 전담, 간결한 독살 (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "Zockify의 간결한 디스커버리 시즌 목록으로, 추천 디스커버리 시즌 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 출혈과 약점 노출은 없습니다. 독 4중첩에서 독 칼, 없으면 난도질(2점부터, 사브르 베기가 있으면 4점부터), 5점에서 독살, 그다음 장갑 룬 연계 점수 생성 기술. 소멸과 냉혈 폭딜은 직접 판단합니다."
L["rm.sod.rogue.tank.Name"] = "방어 전담 (SoD)"
L["rm.sod.rogue.tank.Description"] = "디스커버리 시즌 방어 전담 로테이션으로, 얕은 상처일 뿐을 새겼을 때 선택됩니다. 시뮬레이터 6단계, Icy Veins, Zockify, Warcraft Tavern을 바탕으로 만들었습니다. 반격, 재사용 대기시간마다 맹고쉬, 연계 점수 1점부터 칼춤(3점부터 갱신), 3점부터 난도질(4점부터 갱신), 적이 셋 이상이면 칼날 부채, 혈폭풍, 나팔총, 칼춤이 걸려 있는 동안 나팔총, 두 강화 효과가 모두 있으면 5점에서 절개, 기력이 낮으면 독 칼, 그다음 사브르 베기, 절단 또는 사악한 일격. 알림: 그룹에서 내 대상이 다른 사람을 공격하면 놀리기, 발차기, 생명력 절반 미만에서 회피, 폭풍의 칼날, 아드레날린 촉진, 엉겅퀴 차, 무기 독(보조 무기 독은 보조 무기가 있을 때만). 그림자 밟기와 피부 독 담당은 직접 판단합니다."
L["rm.tbc.rogue.dps.simulator.Name"] = "근접 공격 전담 (시뮬레이터)"
L["rm.tbc.rogue.dps.simulator.Description"] = "1–70레벨, 모든 전문화용입니다. 은신 상태에서: 사전계획, 그다음 혼자일 때는 비열한 습격, 그룹에서는 목조르기, 그 외에는 매복(주무기로 단검을 든 경우). 전투 중: 반격, 연계 점수 2점부터 난도질(마지막 2초 안에 갱신), 곧 죽을 대상에게 절개, 5점에서는 오래 유지될 대상에게 파열(폭풍의 칼날로 광역 공격 중에는 제외), 그 외에는 절개. 대상이 나를 공격하지 않으면 절단 또는 기습(단검)으로, 그 외에는 과다출혈 또는 사악한 일격으로 연계 점수를 쌓습니다. 빠진 독, 발차기, 폭풍의 칼날과 아드레날린 촉진, 냉혈, 회피를 알려 줍니다. 약점 노출, 급소 가격, 교란, 소멸, 위치 선정은 직접 판단합니다."
L["rm.tbc.rogue.dps.wowhead.Name"] = "근접 공격 전담 (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "1–70레벨, 모든 전문화용이며 Wowhead를 따릅니다. 은신 시작 기술, 연계 점수 생성 기술, 알림은 시뮬레이터 버전과 같지만, 난도질은 연계 점수 1점부터 시작하고 5점 마무리 기술은 모두 절개입니다: 파열은 없습니다. 약점 노출, 급소 가격, 교란, 소멸, 위치 선정은 직접 판단합니다. 추천 시뮬레이터 근접 공격 전담 기본 제공 로테이션의 대안이며 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요."
